                if i >= len(json_str):
                    raise ValueError("Unexpected end of string")
                char = json_str[i]
                if char == 'n':
                    result.append('\n')
                elif char == 'r':
                    result.append('\r')
                elif char == 't':
                    result.append('\t')
                elif char == '\\':
                    result.append('\\')
                elif char == '"':
                    result.append('"')
                else:
                    raise ValueError("Invalid escape sequence in string")
            else:
                result.append(json_str[i])
            i += 1
        if i >= len(json_str) or json_str[i] != '"':
            raise ValueError("Unexpected end of string")
        i += 1
        return ''.join(result)

