    def parse_value(json_str, pos):
        if json_str[pos] == '{':
            return parse_object(json_str, pos)
        elif json_str[pos] == '[':
            return parse_array(json_str, pos)
        elif json_str[pos] == '"':
            return parse_string(json_str, pos)
        elif json_str[pos] == 't' and json_str[pos:pos+4] == 'true':
            return True
        elif json_str[pos] == 'f' and json_str[pos:pos+4] == 'false':
            return False
        elif json_str[pos] == 'n' and json_str[pos:pos+4] == 'null':
            return None
        elif json_str[pos].isdigit() or json_str[pos] == '-':
            return parse_number(json_str, pos)
        else:
            raise ValueError("Invalid JSON")

    def parse_object(json_str, pos):
        result = {}
        pos += 1  # Skip '{'
        while json_str[pos] != '}':
            key = parse_string(json_str, pos)
            pos += 1  # Skip ':'
            value = parse_value(json_str, pos)
            result[key] = value
            pos += 1  # Skip ','
        pos += 1  # Skip '}'
        return result

    def parse_array(json_str, pos):
        result = []
        pos += 1  # Skip '['
        while json_str[pos] != ']':
            value = parse_value(json_str, pos)
            result.append(value)
            pos += 1  # Skip ','
        pos += 1  # Skip ']'
