def parse_json(json_str):
    def parse_token(json_str):
        nonlocal index
        char = json_str[index]
        if char == '{':
            return parse_object(json_str)
        elif char == '[':
            return parse_array(json_str)
        elif char == '"':
            return parse_string(json_str)
        elif char.isdigit() or char == '-':
            return parse_number(json_str)
        elif char == 't':
            return parse_boolean(json_str, 'true')
        elif char == 'f':
            return parse_boolean(json_str, 'false')
        elif char == 'n':
            return parse_null(json_str)
        else:
            raise ValueError(f"Unexpected character: {char}")

    def parse_object(json_str):
        nonlocal index
        result = {}
        while index < len(json_str) and json_str[index] != '}':
            key = parse_token(json_str)
            if index >= len(json_str) or json_str[index] != ':':
                raise ValueError("Expected ':' after object key")
            index += 1
            value = parse_token(json_str)
            result[key] = value
            if index < len(json_str) and json_str[index] == ',':
                index += 1
        if index >= len(json_str) or json_str[index] != '}':
            raise ValueError("Expected '}' at the end of object")
        index += 1
        return result

    def parse_array(json_str):
        nonlocal index
        result = []
        while index < len(json_str) and json_str[index] != ']':
            value = parse_token(json_str)
            result.append(value)
            if index < len(json_str) and json_str[index] == ',':
                index += 1
        if index >= len(json_str) or json_str[index] != ']':
            raise ValueError("Expected ']' at the end of array")
        index += 1
        return result

    def parse_string(json_str):
        nonlocal index
        result = []
        while index < len(json_str) and json_str[index] != '"':
            if json_str[index] == '\\':
                index += 1
                if index >= len(json_str):
                    raise ValueError("Unexpected end of string")
                char = json_str[index]
                index += 1
                if char == 'n':
                    result.append('\n')
                elif char == 'r':
                    result.append('\r')
                elif char == 't':
                    result.append('\t')
                elif char == '\\':
                    result.append('\\')
                elif char == '"':
                    result.append('"')
                else:
                    raise ValueError(f"Unknown escape sequence: {char}")
            else:
                result.append(json_str[index])
            index += 1
        if index >= len(json_str) or json_str[index] != '"':
            raise ValueError("Expected '\"' at the end of string")
        index += 1
        return ''.join(result)

    def parse_number(json_str):
        nonlocal index
        result = []
        if json_str[index] == '-':
            result.append('-')
            index += 1
        if index >= len(json_str) or not json_str[index].isdigit():
            raise ValueError("Invalid number format")
        while index < len(json_str) and json_str[index].isdigit():
            result.append(json_str[index])
            index += 1
        if index < len(json_str) and json_str[index] == '.':
            result.append('.')
