import re

def parse_json(json_str):
    def parse_value(tokens):
        if tokens[0] == 'null':
            tokens.pop(0)
            return None
        elif tokens[0] == 'true':
            tokens.pop(0)
            return True
        elif tokens[0] == 'false':
            tokens.pop(0)
            return False
        elif tokens[0] == '{':
            tokens.pop(0)  # Consume the opening brace
            result = {}
            while tokens[0] != '}':
                if tokens[0] != '"':
                    raise ValueError("Expected a string key in object")
                key = parse_string(tokens)
                if tokens[0] != ':':
                    raise ValueError("Expected a colon after the key")
                tokens.pop(0)  # Consume the colon
                value = parse_value(tokens)
                result[key] = value
                if tokens[0] == ',':
                    tokens.pop(0)  # Consume the comma
            tokens.pop(0)  # Consume the closing brace
            return result
        elif tokens[0] == '[':
            tokens.pop(0)  # Consume the opening bracket
            result = []
            while tokens[0] != ']':
                value = parse_value(tokens)
                result.append(value)
                if tokens[0] == ',':
                    tokens.pop(0)  # Consume the comma
            tokens.pop(0)  # Consume the closing bracket
            return result
        elif tokens[0] == '"':
            return parse_string(tokens)
        elif tokens[0].isdigit():
            return parse_number(tokens)
        else:
            raise ValueError("Invalid JSON token")

    def parse_string(tokens):
        tokens.pop(0)  # Consume the opening quote
        result = ''
        while tokens[0] != '"':
            if tokens[0] == '\\':
                tokens.pop(0)  # Consume the backslash
                if tokens[0] in ('"', '\\', '/', 'n', 't', 'r', 'f'):
                    result += tokens.pop(0)
                elif tokens[0] == 'u':
                    tokens.pop(0)  # Consume the 'u' for hex
                    hex_value = tokens.pop(0)
                    if len(hex_value) != 4 or not all(c in '0123456789abcdefABCDEF' for c in hex_value):
                        raise ValueError("Invalid hex escape sequence in string")
                    result += chr(int(hex_value, 16))
                else:
                    raise ValueError("Invalid escape sequence in string")
            else:
                result += tokens.pop(0)
        tokens.pop(0)  # Consume the closing quote
        return result

    def parse_number(tokens):
        if tokens[0] == '-':
            tokens.pop(0)  # Consume the negative sign
        if not tokens[0].isdigit():
            raise ValueError("Invalid number format")
        result = ''
        while tokens[0].isdigit():
            result += tokens.pop(0)
        if tokens[0] == '.':
            tokens.pop(0)  # Consume the decimal point
            if not tokens[0].isdigit():
                raise ValueError("Invalid number format")
            result += tokens.pop(0)
            while tokens[0].isdigit():
                result += tokens.pop(0)
        if tokens[0] in ('e', 'E'):
            tokens.pop(0)  # Consume the exponent
            if tokens[0] in ('+', '-'):
                tokens.pop(0)  # Consume the sign
            if not tokens[0].isdigit():
                raise ValueError("Invalid number format")
            result += tokens.pop(0)
            while tokens[0].isdigit():
                result += tokens.pop(0)
        try:
            return int(result)
        except ValueError:
            return float(result)

    def tokenize(json_str):
        tokens = []
        i = 0
        while i < len(json_str):
            if json_str[i] == '"':
                j = i + 1
                while j < len(json_str) and json_str[j] != '"':
                    j += 1
                tokens.append(json_str[i:j+1])
                i = j + 1
            elif json_str[i].isspace():
                i += 1
            elif json_str[i] in ('{', '}', '[', ']', ',', ':'):
                tokens.append(json_str[i])
                i += 1
            elif json_str[i].isdigit() or json_str[i] in ('+', '-', '.'):
                j = i + 1
                while j < len(json_str) and (json_str[j].isdigit() or json_str[j] in ('+', '-', '.')):
                    j += 1
                tokens.append(json_str[i:j])
                i = j
            else:
                raise ValueError(f"Unexpected character: '{json_str[i]}'")
        return tokens

    # Handle leading whitespace
    json_str = re.sub(r'^\s+', '', json_str)

    # Remove comments if present
    json_str = re.sub(r'//.*?$|/\*.*?\*/', '', json_str, flags=re.DOTALL)

    # Remove any remaining whitespace
    json_str = re.sub(r'\s+', '', json_str)

    # Tokenize the JSON string
    tokens = tokenize(json_str)

    # Parse the tokens into a JSON object
    return parse_value(tokens)

