def parse_json(json_str):
    def parse_bool(s):
        if s == "true":
            return True
        elif s == "false":
            return False
        else:
            raise ValueError("Invalid boolean value")

    def parse_number(s):
        try:
            return int(s)
        except ValueError:
            try:
                return float(s)
            except ValueError:
                raise ValueError("Invalid number")

    def parse_string(s):
        # Remove surrounding quotes and unescape double quotes
        if s.startswith('"') and s.endswith('"'):
            return s[1:-1].replace('\\"', '"')
        else:
            raise ValueError("Invalid string")

    def parse_array(s):
        # Remove the brackets and split by commas
        elements = s[1:-1].split(',')
        parsed_elements = []
        for element in elements:
            parsed_elements.append(parse_json(element.strip()))
        return parsed_elements

    def parse_object(s):
        # Remove the braces and split by commas
        pairs = s[1:-1].split(',')
        parsed_pairs = {}
        for pair in pairs:
            key, value = pair.split(':', 1)
            key = key.strip()
            value = parse_json(value.strip())
            if key in parsed_pairs:
                raise ValueError("Duplicate key in object")
            parsed_pairs[key] = value
        return parsed_pairs

    if json_str[0] == '{':
        return parse_object(json_str)
    elif json_str[0] == '[':
        return parse_array(json_str)
    elif json_str.lower() == 'true':
        return True
    elif json_str.lower() == 'false':
        return False
    elif json_str.lower() == 'null':
        return None
    elif json_str.isdigit() or (json_str[0] in ["+", "-"] and json_str[1:].isdigit()):
        return parse_number(json_str)
    elif json_str.startswith('"') and json_str.endswith('"'):
        return parse_string(json_str)
    else:
        raise ValueError("Invalid JSON")

