    def parse_whitespace(json_str):
        i = 0
        while i < len(json_str) and json_str[i].isspace():
            i += 1
        return json_str[i:]

    def parse_number(json_str):
        i = 0
        if json_str[i] in '+-':
            i += 1
        if json_str[i] in '0123456789':
            i += 1
            while i < len(json_str) and json_str[i] in '0123456789':
                i += 1
        else:
            raise ValueError("Invalid number")
        if json_str[i] in '.':
            i += 1
            if i < len(json_str) and json_str[i] in '0123456789':
                i += 1
                while i < len(json_str) and json_str[i] in '0123456789':
                    i += 1
            else:
                raise ValueError("Invalid number")
        if json_str[i] in 'eE':
            i += 1
            if i < len(json_str) and (json_str[i] in '+-'):
                i += 1
            if i < len(json_str) and json_str[i] in '0123456789':
                i += 1
                while i < len(json_str) and json_str[i] in '0123456789':
                    i += 1
            else:
                raise ValueError("Invalid number")
        return json_str[i:]

    def parse_string(json_str):
        i = 1
        json_str = parse_whitespace(json_str)
        if json_str[i] != '"':
            raise ValueError("Invalid string")
        i += 1
        result = []
        while i < len(json_str) and json_str[i] != '"':
            if json_str[i] == '\\':
                i += 1
                if json_str[i] in '"\\/bfnrt':
                    result.append(json_str[i])
                elif json_str[i] == 'u':
                    result.append(chr(int(json_str[i+1:i+5], 16)))
                    i += 5
                else:
                    raise ValueError("Invalid escape sequence")
            else:
                result.append(json_str[i])
            i += 1
        if i == len(json_str) or json_str[i] != '"':
            raise ValueError("Invalid string")
        i += 1
        return ''.join(result)

    def parse_array(json_str):
        i = 1
        json_str = parse_whitespace(json_str)
        if json_str[i] != '[':
            raise ValueError("Invalid array")
        i += 1
        result = []
        while i < len(json_str) and json_str[i] != ']':
            result.append(parse_value(json_str))
            if i < len(json_str) and json_str[i] == ',':
                i += 1
                json_str = parse_whitespace(json_str)
            else:
                break
        if i == len(json_str) or json_str[i] != ']':
            raise ValueError("Invalid array")
        i += 1
        return result

    def parse_object(json_str):
        i = 1
        json_str = parse_whitespace(json_str)
        if json_str[i] != '{':
            raise ValueError("Invalid object")
        i += 1
        result = {}
        while i < len(json_str) and json_str[i] != '}':
            key = parse_string(json_str)
            json_str = parse_whitespace(json_str)
            if json_str[i] != ':':
                raise ValueError("Invalid object")
            i += 1
            value = parse_value(json_str)
            result[key] = value
            json_str = parse_whitespace(json_str)
            if i < len(json_str) and json_str[i] == ',':
                i += 1
                json_str = parse_whitespace(json_str)
            else:
                break
        if i == len(json_str) or json_str[i] != '}':
            raise ValueError("Invalid object")
        i += 1
        return result

    def parse_value(json_str):
        json_str = parse_whitespace(json_str)
        if json_str[i] == '"':
            return parse_string(json_str)
        elif json_str[i] in '0123456789':
            return parse_number(json_str)
        elif json_str[i] == '[':
            return parse_array(json_str)
        elif json_str[i] == '{':
            return parse_object(json_str)
        elif json_str[i] == 't':
            if json_str[i:i+3] == 'true':
                i += 3
                return True
            else:
                raise ValueError("Invalid true")
        elif json_str[i] == 'f':
            if json_str[i:i+4] == 'false':
                i += 4
                return False
            else:
                raise ValueError("Invalid false")
        elif json_str[i] == 'n':
            if json_str[i:i+3] == 'null':
                i += 3
                return None
            else:
                raise ValueError("Invalid null")
        else:
            raise ValueError("Invalid value")

    return parse_value(json_str)

