def parse_json(json_str):
    def parse_element(index):
        nonlocal json_str
        char = json_str[index]

        if char == '{':
            return parse_object()
        elif char == '[':
            return parse_array()
        elif char.isdigit() or (char == '-' and json_str[index + 1].isdigit()):
            return parse_number()
        elif char in ('"', "'"):
            return parse_string()
        elif char in ('t', 'f', 'n'):
            return parse_boolean()
        elif char == ',' or char == '}':
            return None

        raise ValueError("Invalid character in JSON string")

    def parse_object():
        result = {}
        json_str = json_str[1:]
        while json_str:
            key = parse_element(0)
            if key is None:
                break
            json_str = json_str[len(key) + 1:]
            if json_str[0] != ':':
                raise ValueError("Missing colon in JSON object")
            json_str = json_str[1:]
            value = parse_element(0)
            if value is None:
                raise ValueError("Invalid JSON object value")
            result[key] = value
            json_str = json_str[1:]
            if json_str[0] == ',':
                json_str = json_str[1:]
            elif json_str[0] == '}':
                return result
            else:
                raise ValueError("Invalid character after JSON object element")

        raise ValueError("Invalid JSON object")

    def parse_array():
        result = []
        json_str = json_str[1:]
        while json_str:
            element = parse_element(0)
            if element is None:
                break
            result.append(element)
            json_str = json_str[1:]
            if json_str[0] == ',':
                json_str = json_str[1:]
            elif json_str[0] == ']':
                return result
            else:
                raise ValueError("Invalid character after JSON array element")

        raise ValueError("Invalid JSON array")

    def parse_number():
        num_str = ''
        while json_str and (json_str[0].isdigit() or json_str[0] in ('-', '+', '.', 'e', 'E')):
            num_str += json_str[0]
            json_str = json_str[1:]

        try:
            if '.' in num_str or 'e' in num_str or 'E' in num_str:
                return float(num_str)
            else:
                return int(num_str)
        except ValueError:
            raise ValueError("Invalid number in JSON string")

    def parse_string():
        result = ''
        char = json_str[0]
        json_str = json_str[1:]
        while json_str and (char != '"' and char != "'"):
            result += char
            char = json_str[0]
            json_str = json_str[1:]
        if char != '"' and char != "'":
            raise ValueError("Invalid string in JSON string")
        return result

    def parse_boolean():
        if json_str.startswith("true"):
            json_str = json_str[4:]
            return True
        elif json_str.startswith("false"):
            json_str = json_str[5:]
            return False
        elif json_str.startswith("null"):
            json_str = json_str[4:]
            return None
        else:
            raise ValueError("Invalid boolean in JSON string")

    return parse_element(0)

